unit.script:
function onEnterSequence(seq) {
	if( seq == Sequences.ChaosStorm ) {
		stopAreas(unit, Skill.SuperEliteDemon_Bomb);
		stopAreas(unit, Skill.SuperEliteDemon_Slam);
		moveToPosition(foe.getOrigin(), true);
	}
}

function onReachMoveTarget() {
	if( currentSequence == Sequences.ChaosStorm )
		forceCast(Skill.SuperEliteDemon_Storm);
}

function onSkillEnd(skill, cancel) {
	switch(currentSequence) {
		case Sequences.ChaosStorm:
			if(isSkill(skill, Skill.SuperEliteDemon_Storm))
				leaveSequence();
		default:
	}
}

function onEnterCombat() {
	forceCast(Skill.SuperEliteDemon_FireWall);
	addAtb(unit, Attribute.SpecialEnergy, 100);
}

function onEnterCombat() {
	var sk = unit.forceUseSkill(Skill.SuperEliteDemon_FireWall);
	sk.onCompletion = () -> {
		forceCast(Skill.FaerieEliteDemon_NightRain);
	};
}

function onDeath(dmg) {
	unit.forceUseSkill(Skill.FaerieEliteDemon_FalseClone_Explosion);
}

function onDeath(dmg) {
	setChallenge(unit, Ach.Complete_Z1_Ratsar_HM_Special, false);
}

function onInit() {
	addStatus(Skill.Demon_Gate_Visual_Status);
}

var waterBreathSkill = Skill.ManfishBoss_WaterBreath;

var nextCrabSpawn = 0.;
var crabPoints = [];
var activeCrabs = [];

function initCrabPoints() {
	clear(crabPoints);
	addCrabSpawn("CrabA");
	addCrabSpawn("CrabB");
	addCrabSpawn("CrabC");
	addCrabSpawn("CrabD");
	addCrabSpawn("CrabE");
	addCrabSpawn("CrabF");
	trace("Added " + crabPoints.length + " crab spawns");
}

function canBlockRotation() {
	return !isFree() && currentSequence != null;
}

function onEnterCombat() {
	initCrabPoints();
}

function onLeaveCombat() {
	clearCrabs();
}

function onCombatUpdate(dt) {
	updateCrabs(dt);
}

function onEnterSequence(seq) {
	switch(seq) {
		case Sequences.WaterBreath:
			moveToPosition(foe.getOrigin());
		default:
	}
}

function onReachMoveTarget() {
	switch(currentSequence) {
		case Sequences.WaterBreath:
			lookTowards("B", 0.5);
			if (isHeroicMode) {
				forceCast(Skill.ManfishBoss_Bubble_Roam);
			}
			forceCast(waterBreathSkill);
		default:
	}
}

function onSkillEnd(skill, cancel) {
	switch(currentSequence) {
		case Sequences.WaterBreath:
			if(isSkill(skill, waterBreathSkill)) {
				leaveSequence();
				stopAreas(unit, Skill.ManfishBoss_Bubble_Roam);
			}
		default:
	}
}



function onStatusEnd(status, cancel) {
	if (!cancel && status.kind == Skill.ManfishBoss_WaterBreath_Shield) {
		var totems = 0;
		for (f in unit.getSpawnedFoes())
			if (f.kind == Unit.Nepsilon_Totem && !f.isDead())
				totems++;
		if (totems >= AchConst.Complete_Z1_ManfishRuins_HM_Special.Totems)
			setChallenge(unit, Ach.Complete_Z1_ManfishRuins_HM_Special, true);
	}
}

function addCrabSpawn(name) {
	var pt = getPoint(name);
	if(pt != null)
		crabPoints.push(pt);
}

function updateCrabs(dt) {
	filterOut(activeCrabs, c -> c.isDead());
	for(c in activeCrabs) {
		if(unit.targetUnit != null && c.target == null)
			c.aggroUnit(unit.targetUnit);
	}
}

function clearCrabs() {
	for(c in activeCrabs) {
		disbandFoe(c);
	}
	clear(activeCrabs);
}

var nayaSkill = Skill.R1CrabBoss_NayasFury;
var chargeSkill = Skill.R1CrabBoss_HuntDown;
var moveStatus: st.skill.Status;

function onCombatUpdate(dt) {
	switch(currentSequence) {
		case Sequences.NayasFury:
		default:
			if(isSkillReady(unit, nayaSkill)) {
				requestSequence(Sequences.NayasFury);
			}
	}
	/*if(isFree() && getCombatTimeSinceLastSkill() > vars.var2)
		forceCast(chargeSkill);*/
}

function onEnterSequence(seq) {
	switch(seq) {
		case Sequences.NayasFury:
			moveTo("A");
			moveStatus = addStatus(Skill.R1CrabBoss_NayasFuryMoveStatus);
		default:
			if(moveStatus != null)
				moveStatus.stop();
			moveStatus = null;
	}
}

function onReachMoveTarget() {
	switch(currentSequence) {
		case Sequences.NayasFury:
			if(moveStatus != null)
				moveStatus.stop();
			moveStatus = null;
			forceCast(nayaSkill);
		default:
	}
}

function onSkillEnd(skill, cancel) {
	switch(currentSequence) {
		case Sequences.NayasFury:
			if(isSkill(skill, nayaSkill)) {
				leaveSequence();
				updateAggro();
			}
		default:
	}
}

function onCombatEnd() {
	if(moveStatus != null)
		moveStatus.stop();
	moveStatus = null;
}

var hitDistance = 8;

function onUpdate(dt) {
	var target = foe.target.get();

	// if (target == null || target.removed) {
	// 	moveToSpike();
	// }

	// if (target != null) {
	// 	foeRequestSkill(foe, Skill.GiantCrawler_Slash_Skill, target);
	// }
}

function moveToSpike() {
	var nearest = getNearestElement(unit.position, 150, Element.R1CrabBoss_Shard, unit);
	foe.target = nearest;
	if (nearest != null) {
		moveToPosition(nearest.position);
	}
}

// var1: How many sprayed fondue runs in a row
// var2: Room with inverted trains (negative value to disable)
// var3: move speed factor when changing room or using SprayedFondue
// salvo: cooldown between two train in seconds for each phase
// wait1: how long before dockerTrain departs when dockers are cleared
// delay: how many seconds ahead of trains to trigger avoidance (negative value means no avoidance)
// range: Distance to avoidance point to trigger Chuck's dodge
// summon1: DockerTrain foe group

function onEnterCombat() {
	setChallenge(unit, Ach.Complete_Z2_Munster_HM_Special, true);
}

function onEnterPhase(from) {
    if(phase == 2) {
        triggerSpawner(unit, Element.Mokshi_Spawner_CannonDefense);
    }
}

function onEnterSequence(k) {
    if(k == Sequences.EnterChrysalis) {
        forceSequence(Sequences.InChrysalis);
        forceCast(Skill.Mokshi_EnterChrysalis);
    }
}

function onSkillEnd(s, cancel) {
    if (s.kind == Skill.Mokshi_Phase2Screech) {
        forceSequence(Sequences.MoveToRoof);
        moveToElement(Element.Mokshi_ChrysalisPosition, true);
        requestSequence(Sequences.EnterChrysalis);
    }
}

function onStatusEnd(status, cancel) {
    if(inCombat && status.kind == Skill.Mokshi_ChrysalisStatus) {
        leaveSequence(Sequences.InChrysalis);
        goToPhase(3);
    }
}

function onCombatUpdate(dt) {
    var mokshi = toMokshi(unit);
    if(currentSequence == Sequences.InChrysalis) {
        mokshi.tryCastChrysalisLaser();
    }
    else if (phase == 3) {
        mokshi.tryCastEfflorescence(dt);
    }
}

function onElementDestroyed(element) {
	trace("destroy");
	if (element.isOfType(Element.Mokshi_Hexagonal_Platform_Heroic)) {
		summonFoe(Unit.Mokshi_Heroic_Summon, element.position);
	}
}

function onEnterCombat() {
	setChallenge(unit, Ach.Complete_Z2_Abyss_HM_Special, true);
}

var skillGolcano = Skill.Golcano_ShieldApply;

function onEnterSequence(seq) {
	switch(seq) {
		case Sequences.GolcanoInterphase:
		moveTo("A");
		default:
	}
}

function onReachMoveTarget() {
	switch(currentSequence) {
		case Sequences.GolcanoInterphase:
			forceCast(skillGolcano);
		default:
	}
}

function onSkillEnd(skill, cancel) {
	switch(currentSequence) {
		case Sequences.GolcanoInterphase:
			if(isSkill(skill, skillGolcano))
				leaveSequence();
		default:
	}
}

function onEnterCombat() {
	setChallenge(unit, Ach.Complete_Z3_Phrixes_HM_Special, true);
}

function onCombatUpdate(dt) {
	if(!isMoving() && foe.summonOwner != null)
		moveToPosition(foe.summonOwner.position);
}

function onDeath(dmg) {
	if (dmg.source != unit)
		setChallenge(unit, Ach.Complete_Z3_Phrixes_HM_Special, false);
}

function onEnterCombat() {
	forceCast(Skill.Phrixes_H_NG_Spawn);
}

function onCombatUpdate(dt) {
	if(combatTime > vars.delay) {
		unlockObjectiveBossAlt(unit);
	}
}

function onInit() {
	addStatus(Skill.Demon_Gate_Visual_Status);
}

function onInit() {
	addStatus(Skill.Phrixes_H_NGGate_Visual_Status);
}

function onEnterCombat() {
    enableSpawner(unit, Element.Cleodora_Feeders, function(feeder, spawn) {
        foeRequestSkill(feeder, Skill.CleodoraFeeder_Beam, unit);
    });

    // enableSpawner(unit, Element.Cleodora_Guards);
}

function onDeath(dmg) {
	disableSpawner(unit, Element.Cleodora_Feeders);
}

function onEnterPhase(from) {
    if(phase > 2) {
        disableSpawner(unit, Element.Cleodora_Feeders);
        disableSpawner(unit, Element.Cleodora_Guards);
    }
	if( phase == 4 ) {
		forceSequence(Sequences.Afflux);
		for( u in unit.getAllHeroes() ) {
			u.addStatus(Skill.Stun, 1, null, unit);
		}
		stopAllAreas(unit);
		moveTo("Center");
	}
}

function onReachMoveTarget() {
	if( currentSequence == Sequences.Afflux ) {
		forceCast(Skill.Cleodora_SparkAfllux_Start);
	}
}

function onInit() {
    forceCast(Skill.CleodoraEgg_Cast);
}

var spinCount = 0;

function onSkillEnd(s, cancel) {
	if (s.kind == Skill.Ratsar_Spin) {
		if (cancel) {
			spinCount = 0;
		}
		else {
			spinCount++;
			if (spinCount%2 != 0)
				unit.forceUseSkill(Skill.Ratsar_Spin);
		}
	}

}

function onEnterCombat() {
	setChallenge(unit, Ach.Complete_Z1_Ratsar_HM_Special, true);
}

skill.script:
function onBlockEval( hit ) {
	if( hit.hasBeat(GameBeat.BlockWellTimed) ) {
		addStatus(owner, Skill.PhysicalBlock_Status_WellTimed);
		hit.block += vars.var2;
	}
}

function onSkillProc(ctx) {
	if(ctx.skill.isFinalAttack()) {
		ctx.dmgMult += vars.damage;
		stop();
	}
}

function onBlockEval( hit ) {
	if( hit.hasBeat(GameBeat.BlockWellTimed) ) {
		addStatusDuration(hit.source, Skill.Root, vars.dur1);
		hit.block += vars.var2;
	}
}

function onBlockEval( hit ) {
	if( hit.hasBeat(GameBeat.BlockWellTimed) ) {
		hit.block += vars.var2;
	}
}

function onClientStep(s) {
	if(s.kind == Steps.CheckGround) {
		if(!owner.body.grounded)
			localPlayStep(Steps.Air);
	}
}

var timeStationary = 0.0;

function onSkillProc(ctx) {
	if (!ctx.skill.isPassive()) {
		removeBuff();
	}
}

function onUpdate(dt) {
	if (ownerHero != null && ownerHero.gliding) {
		removeBuff();
	}
	if (Math.abs(owner.moveX) < 0.01 && Math.abs(owner.moveY) < 0.01) {
		timeStationary += dt;
	} else {
		timeStationary = 0;
	}

	if (timeStationary > vars.duration) {
		removeBuff();
	}
}

function removeBuff() {
	removeStatus(owner, status.kind);
}

function onInflictHit(hit) {
	if(hit.isFirstHit)
		ownerHero.gainSparkParticle(10);
}

function onInflictDamage(dmg) {
	addDmg(dmg.amount, dmg.skillId, dmg.target);
}

function onProxyDamage(dmg) {
	addDmg(dmg.amount, dmg.skillId, dmg.target);
}

function addDmg(dmg:Float, skillId, target) {
	if (skillId == Skill.SparkSurge_Mark)
		return;
	var amount = dmg * vars.var1;
	addStatus(target, Skill.SparkSurge_Mark, amount);
}

function onStop(ctx) {
	for(s in getInflictedStatuses(Skill.SparkSurge_Mark)) {
		var count = s.consume();
	}
}

function onDamage(dmg) {
	if( dmg.critical ) {
		resetCooldown(Skill.Axe_Boomerang_Skill1);
	}
}

function onDamageEval(hit) {
	if( hit.target.hasStatusType(StatusType.Bleed) ) {
		hit.dmgMult += vars.var1;
	}
}

function onDamage(dmg) {
	var amount = dmg.amount * vars.var1;
	addStatus(dmg.target, Skill.Axe_Boomerang_Skill1_Status, amount);
}

function onDamageEval(hit) {
	if( rank >= 3 ) {
		hit.critDmgMult += vars.var2;
	}
}

var cd = 0.;
function onInflictDamage(dmg) {
	if (rank >= 3 && dmg.isPhysical && dmg.critical && cd <= 0) {
		setDynVal(1, vars.var2 * owner.maxHealth);
		playStep(Steps.Heal, owner);
		cd = vars.time;
	}
}
function onRegUpdate(dt) {
	if (cd > 0) {
		cd -= dt;
	}
}

function onFirstHit(h) {
	addStatus(owner, Skill.Mace_Benediction_Status);

}

function onInflictDamage(dmg) {
	if (dmg.isFirstHit && dmg.skillId == Skill.Mace_Benediction_Combo && rank >= 3) {
		if (dmg.critical) {
			addStatus(owner, Skill.Mace_Benediction_Skill1_Proc);
			resetCooldown(Skill.Mace_Benediction_Skill1);
		}
	}
	if (rank >= 2 && dmg.stepId == Steps.Hit) {
		playStep(Steps.Area, dmg.target);
	}
}

var Benediction = Skill.Mace_Benediction_Status;
var Buff = Skill.Mace_Benediction_Skill1_Status;

function onStep(s) {
	if (s.kind == Steps.Consume) {
		if (hasStatusMaxStacked(owner, Benediction))
			addStatus(owner, Buff);

		var buffStacks = owner.getStatusCount(Benediction, owner);
		owner.tryConsumeStatus(Benediction, owner);
		var refund = 0;
		if (rank >= 3) {
			for (i in 0...buffStacks) {
				if (checkProba(vars.chance)) {
					refund++;
				}
			}
		}
		if (refund > 0) {
			owner.addStatus(Benediction, refund);
		}
	}
}

function onDamageEval(hit) {
	if (rank >= 2) {
		hit.critDmgMult += vars.damage;
	}
}


function haveInstantCast() {
	return owner.getStatus(Skill.Mace_Benediction_Skill1_Proc) != null;
}

function shouldPlayInstantly() {
	return haveInstantCast();
}

function shouldHighlightSkill() {
	return haveInstantCast();
}

function onProc(ctx) {
	removeStatus(owner, Skill.Mace_Benediction_Skill1_Proc);
}

var Buff = Skill.Mace_Benediction_Passive_Status;

function onSkillProc(ctx) {
	if (ctx.isWeaponSkill) {
		removeStatus(owner, Buff);
		addStatus(owner, Buff, vars.var1);
	}
}

var Benediction = Skill.Mace_Benediction_Status;
var SelfBuff = Skill.Mace_Benediction_Passive_Status;

function onInflictDamage(dmg) {
	if (dmg.isAttack) {
		playStep(Steps.Damage, dmg.target);
		if (dmg.isFirstHit) {
			consumeStatus(owner, SelfBuff, 1);
			addStatus(owner, Benediction);
		}
	}
}

function onInflictDamageEval(hit) {
	if (rank >= 3) {
		if (hit.isAttack) {
			hit.critChance += sourceSkill.vars.chance;
		}
	}
}

function onFirstHit(hit) {
	if(rank >= 3) {
		reduceWeaponsCooldown(vars.time);
	}
}

function onDamageEval(hit) {
	if(rank >= 2) {
		hit.critChance += vars.var1;
	}
}

function onDamage(dmg) {
	if(dmg.critical && rank == 3) {
		addStatus(dmg.target, Skill.Sword_Start_Skill1Status);
	}
}

function onFirstHit(hit) {
	if( checkProba(vars.var1) ) {
		var sk = ownerHero.getOffhandWeaponSkill();
		if(sk != null) {
			sk.reduceCooldown(vars.time);
			if(rank >= 3) {
				playStep(Steps.MagicDamage, hit.target);
			}
		}
	}
}

function onGameBeat(beat, hit) {
	if( beat == GameBeat.AttackBlock) {
		resetCooldown(kind);
	}
	if(rank >= 3 && beat == GameBeat.BlockWellTimed) {
		addStatus(owner, Skill.Sword_Craft_Skill1_Status);
	}
}

function onDamageEval(hit) {
	if(rank >= 2) {
		hit.dmgMult += vars.var1;
	}
}

function onStart(ctx) {
	var stacks = consumeStatus(owner, Skill.Sword_Craft_Skill1_Status);
	if(stacks > 0) {
		ctx.dmgMult += stacks * vars.var3;
	}
}

function onRegUpdate(dt) {
	var count = countEnemiesInRange(vars.range);
	var apply = count >= vars.var1;
	var inCombat = owner.isInCombat;
	setStatus(owner, Skill.Sword_Craft_Passive_Status, apply && inCombat ? 1 : 0);
}

function onStop(ctx) {
	setStatus(owner, Skill.Sword_Craft_Passive_Status, 0);
}

function onGameBeat(beat, hit) {
	if(rank >= 3) {
		if(beat == GameBeat.BlockWellTimed) {
			playStep(Steps.HealArea);
		}
	}
}

function onHealEval(h) {
	if( owner.healthRatio < vars.threshold ) {
		h.critChance = 1;
	}
}

function onHit(hit) {
	if (hit.stepId == Steps.Hit) {
		playStep(Steps.Area);
	}
}

function onHit(hit) {
	if (rank >= 3) {
		addStatus(owner, Skill.Sword_Swarm_Skill1_SelfBuff);
	}
}

function onSkillProc(ctx) {
	if (ctx.skill.isWeaponSkill()) {
		addStatus(owner, Skill.Sword_Swarm_Passive_Swarm);
	}
}

function onInflictDamage(dmg) {
	if( dmg.skillId == Skill.Sword_Swarm_Passive_Swarm) {
		if( checkProba(vars.chance) && rank >= 3 ) {
			addStatus(dmg.target, Skill.Sword_Swarm_Passive_Poison);
		}
		var dmg = dmg.amount;
		var amount = dmg * vars.var2;
		applyHeal(owner, amount);
 	}


}

function onGameBeat(beat, hit) {
	if(rank >= 3 && beat == GameBeat.BlockWellTimed) {
		addStatus(owner, Skill.Shield_Start_Skill1_Status);
	}
}

function onHit(hit) {
	addStatusDuration(hit.target, Skill.Stun, vars.dur1);
}

function onStart(ctx) {
	var stacks = consumeStatus(owner, Skill.Shield_Start_Skill1_Status);
	if(stacks > 0) {
		ctx.dmgMult += stacks * vars.var2;
	}
}

function onGameBeat(beat, dmg) {
	if( beat == GameBeat.AttackBlock) {
		reduceCooldown(Skill.Shield_Craft_Skill1, vars.dur1);
	}
}

var STATUS_KIND = Skill.Shield_Craft_Passive_Status;

function onRegUpdate(dt) {
	if(!isInCooldown()) {
		setStatus(owner, STATUS_KIND);
	}
}

function onReceiveDamageEval(hit) {
	if(isInCooldown()) {
		hit.dmgMult -= vars.var2;
	}
}

/*function onSkillProc(ctx) {
	if(hasStatus(owner, STATUS_KIND)) {
		if(ctx.skill.isFinalAttack()) {
			var armor = getAtb(owner, Attribute.Armor);
			var dmg = armor * vars.var1;
			ctx.dmgAdd += dmg;
			removeStatus(owner, STATUS_KIND);
			consumeCooldown();
		}
	}
}*/

function onInflictDamageEval(hit) {
	if( hasStatus(owner, Skill.Shield_Craft_Passive_Status) && hit.isFinalCombo ) {
		playStep(Steps.MagicDamage, hit.target);
		removeStatus(owner, Skill.Shield_Craft_Passive_Status);
		consumeCooldown();
	}
}

function onProc(ctx) {
	removeStatus(owner, Skill.Shield_OrbitWater_S1_OrbStatus);
	setStatus(owner, Skill.Shield_OrbitWater_S1_OrbStatus, 10);
}

function onHit(hit) {
	if( hit.stepId == Steps.Orb ) {
		consumeStatus(owner, Skill.Shield_OrbitWater_S1_OrbStatus);

		if( hasStatus(owner, Skill.Shield_OrbitWater_S1_OrbStatus) ) {
			playStep(Steps.Area);
		} else {
			var ctx = playStep(Steps.LastOrbArea);
			if (rank >= 3) {
				ctx.dmgMult += 1;
			}
		}
	}
}

function onDamage(dmg) {
	if( rank >= 3 && dmg.stepId == Steps.LastOrbArea ) {
		addStatusDuration(dmg.target, Skill.Stun, vars.dur1);
	}
}

function onGameBeat(b, hit) {
	if( b == GameBeat.AttackBlock ) {
		// Wait next frame so block doesn't trigger the block status.
		if( !hasStatus(owner, Skill.Shield_OrbitWater_P_StatusBlockBuffed) ) {
			wait(0, () -> {
				addWaterInfusion();
			});
		}
	}
}

function onInflictHit(hit) {
	if( hit.isFinalCombo && hit.isFirstHit) {
		addWaterInfusion();
	}
}

function addWaterInfusion() {
	if( !hasStatus(owner, Skill.Shield_OrbitWater_P_StatusBlockBuffed) ) {
		addStatus(owner, Skill.Shield_OrbitWater_P_Status);
	}
}

function onInflictDamage(dmg) {
	if( dmg.hitCount == 1 && dmg.skillId == Skill.Shield_OrbitWater_P_StatusBlockBuffed ) {
		reduceCooldown(Skill.Shield_OrbitWater_S1, vars.dur1);
	}
}

function onStacksChange() {
	if( stacks >= maxStacks ) {
		removeStatus(owner, Skill.Shield_OrbitWater_P_Status);
		addStatus(owner, Skill.Shield_OrbitWater_P_StatusBlockBuffed);
	}

}

function onGameBeat(b,hit) {
	if( b == GameBeat.AttackBlock ) {
		playStep(Steps.Area);
		skill.stop();
	}

}

function onReceiveDamageEval(hit) {
	if (skill.isRunning() && rank >= 3 ) {
		if (hit.blockHit()) {
			playStep(Steps.Hit);
		}
	}
}

var STATUS_KIND = Skill.Shield_Firebreath_Passive_Status;

function onGameBeat(b,hit) {
	if (b == GameBeat.AttackBlock) {
		addStatus(owner, STATUS_KIND);
	}
}

function onReceiveDamage(dmg) {
	if (rank >= 3 && dmg.source != owner) {
		playStep(Steps.ReflectDamage, dmg.source);
