var canReblink:Bool = false;
var Reblink = Skill.Halos_Demon_Skill1_Recast;

var StartStep = Steps.Trigger;
var TpStep = Steps.TP;
var TpBackStep = Steps.TPBack;

var tpPos = null;

function onDamageEval(hit) {
	if (rank >= 2 && hit.target.isUnderAnyCC()) {
		hit.dmgMult += vars.damage;
