function canBlinkBack() : Bool {
	return haveReblinkStatus();
}

function haveReblinkStatus() {
	return hasStatus(owner, Reblink);
}

function removeSkillStatus(s) {
	consumeStatus(owner, Reblink);
}

function onStep(step) {

	if (step.kind == Steps.Area) {
		if (canReblink) {
			if (rank >= 3) {
				playStep(Steps.Shield);
			}
		}
	}

	if (step.kind == StartStep) {
		if (canBlinkBack() && canReblink) {
			removeSkillStatus(Reblink);
			canReblink = false;
			stop();
			return;
		}
	}
	if (step.kind == StartStep) {
		if (!haveReblinkStatus()) {
			addStatusDuration(owner, Reblink, vars.time);
			canReblink = true;

			return;
		}
	}

}

function onClientUpdate(dt) {
	if (returnPosition != null) {
		setVFXPosition(returnPosition, Reblink);
	}
}

function onClientStep(step) {
	if (step.kind == StartStep) {
		if (canBlinkBack() && canReblink) {
			localPlayStep(TpBackStep, null, returnPosition);
			canReblink = false;
			stop();
		} else {
			localPlayStep(TpStep, null, ctx.aimPosition);
		}
	}
	if (step.kind == StartStep) {
		if (!haveReblinkStatus()) {
			returnPosition = skill.ownerUnit.position.clone();
			canReblink = true;
		}
	}

}

function allowAiming() {
	return !canReblink || !canBlinkBack();
}

function checkForceRecast() : Bool {
	return canBlinkBack();
}


function shouldHighlightSkill() : Bool{
	return canBlinkBack();
}

