var dmgStackCount = 0;
function onStart(ctx) {
	var shotDelay = vars.delay;
	var stackCount = getStatusCount(owner, Skill.Crescent_FlowerSpiral_Skill_1_Charge);
	dmgStackCount = stackCount;
	consumeStatus(owner, Skill.Crescent_FlowerSpiral_Skill_1_Charge, 1000);
	if (stackCount == 0) {
		playStep(Steps.StartBaseArea);
		playStep(Steps.StopStep);
	} else {
		for (i in 0...(stackCount + 1)) {
			if (i < stackCount) {
				wait(i * shotDelay, function() {
					playStep(Steps.AdditionalArea);
				});
			} else {
				wait(i * shotDelay, function() {
					playStep(Steps.StartBaseArea);
					playStep(Steps.StopStep);
				});
			}
		};
	}
}

