function tryGetComboPoint(s, skind, isCrit) {
	if (s != null && isSkillCompatible(s)) {
		var points = 0.;
		if(lastSkillProc != skind ) {
			points += vars.var1;
			lastSkillProc = skind;
		}
		if(isCrit && lastSkillCritProc != skind && hasGlobalMastery(Mastery.Rogue_Finisher_M1)) {
			points += 1;
			lastSkillCritProc = skind;
		}
		if (points > 0) {
			addAtb(owner, Attribute.ComboPoint, points);
		}
	}
}

function isSkillCompatible(s) {
	if(s == null || s.isPassive())
		return false;
	return s.isWeaponSkill() || s.isFinalAttack();
}

