var damageBonus = 0.0;
var comboPoint = Skill.Rogue_Finisher_Combo_Point;

function checkComboPoints() {
	if (hasMastery(Mastery.Rogue_Finisher_M2)) {
		if (!hasStatus(owner, comboPoint)) {
			addStatus(owner, comboPoint);
		}
	} else {
		if (hasStatus(owner, comboPoint)) {
			removeStatus(owner, comboPoint);
		}
	}
}

function onStart(ctx) {
	damageBonus = 0.0;
	checkComboPoints();
}

function onCooldownEval(ctx,val) {
	if (hasStatus(owner, Skill.Rogue_UrgeToKill_Status)) {
		return 1;
	}
	return val;
}

function onMasteriesChanged() {
	checkComboPoints();
}

function onStep(s) {
	if(!isServer) return;
	if(s.kind == Steps.Damage || s.kind == Steps.DamageRanged) {
		var consumed = getCp();
		damageBonus = consumed * vars.var1;
	}
	if (s.kind == Steps.ConsumeCP) {
		addAtb(owner, Attribute.ComboPoint, -getCp());
		if( hasMastery(Mastery.Rogue_Finisher_M3) ) {
			addAtb(owner, Attribute.ComboPoint, vars.var3);
		}
	}
}

function getCp() {
	return round(getAtb(owner, Attribute.ComboPoint));
}

function onDamageEval(hit) {
	hit.dmgMult += damageBonus;
}

function onProc(ctx) {
