var SIG = Skill.Rogue_Talent_LethalPoison_Dose_Finisher;
var WS = Skill.Rogue_Talent_LethalPoison_Dose_WeaponSkill;

function onInflictHitNewTarget(ctx) {

	if (ctx.target.isAlly(skill.owner)) { return; }

	if (ctx.isWeaponSkill) {
		applyDose(WS, ctx.target);
	}
	if (ctx.isClassSkill) {
		applyDose(CS, ctx.target);
	}
	if (ctx.isFinalCombo) {
		applyDose(FCA, ctx.target);
	}
	if (ctx.isSignature) {
		applyDose(SIG, ctx.target);
	}
}

function onTryAddStatus(sInf,target) {
	if (sInf.id == Skill.Rogue_Talent_LethalPoison_Status && hasStatus(target, Skill.Rogue_Talent_LethalPoison_Status)) {
		var poison = target.getStatus(Skill.Rogue_Talent_LethalPoison_Status);
		poison.playStep(Steps.Blast);
	}
}

function applyDose(sid, target) {
	addStatus(target, sid);
	checkDoses(target);
}
function updateMarker(target, count) {
	enforceStatusCount(target, Skill.Rogue_Talent_LethalPoison_Dose, count);
}

function checkDoses(target) {
	var statuses = target.getStatuses(s -> isDose(s), owner);
	var doseCount = statuses != null ? Math.round(statuses.length) : 0;
	var doseNeed = vars.var1;

	if (doseCount >= doseNeed) {
		if (hasStatusMaxStacked(target, Skill.Rogue_Talent_LethalPoison_Status)) {
			var poison = target.getStatus(Skill.Rogue_Talent_LethalPoison_Status);
			//poison.playStep(Steps.Blast);
		}
		addStatus(target, Skill.Rogue_Talent_LethalPoison_Status);
		removeStatuses(target, s -> isDose(s));
		updateMarker(target, 0);
	} else {
		updateMarker(target, doseCount);
	}
}


function isDose(s) {
	return s.kind == CS || s.kind == SIG || s.kind == WS || s.kind == FCA;
}

