function onReceiveDamageEval(dmg) {
	if (!hasStatus(owner, Skill.Rogue_Talent_CheatDeath_Cooldown)) {
		var threshold = owner.maxHealth * vars.var1;
		if (owner.health - dmg.amount < threshold) {
			var effectiveDamage = min(threshold - dmg.amount, dmg.amount);
			addStatus(owner, Skill.Rogue_Talent_CheatDeath_Status);
			addStatusDuration(owner, Skill.Rogue_Talent_CheatDeath_Cooldown, vars.cooldown);
			dmg.amount = 0;
			owner.health = threshold;
		}
	}
}

