var lastReadyPrayers = 0;
function onRegUpdate(dt) {
	if (hasMastery(Mastery.Priest_Judgment_M2)) {
		var priest = ownerHero?.priest;
		if (priest != null) {
			var ready = priest.getChargedPrayerCount();
			var gain = ready - lastReadyPrayers;
			if (gain > 0) {
				for (i in 0...gain) {
					reduceCooldown(Skill.Priest_Sig_DivineIntervention, vars.time);
				}
			}
			lastReadyPrayers = ready;
		}
	}
}

function checkEnabled() {
	var priest = ownerHero?.priest;
	if(priest == null)
		return Reason.Invalid;
	if(priest.getChargedPrayerCount() == 0)
		return Reason.RequireActivePrayer;
	return Reason.Ok;
}

