function onRegUpdate(dt) {

	if (!isHeroicMode) { return; }

	var areas = skill.getAreas();
	for (a1 in areas) {
		for (a2 in areas) {
			if (a1 == a2) { continue; }
			var p = getAreaOverlapPoint(a1, a2);

			var existing = explodedAreas.filter(a -> (a.area1 == a1 && a.area2 == a2) || (a.area1 == a2 && a.area2 == a1)).length > 0;
			if (existing) { continue; }
			if (p != null) {
				explodedAreas.push({area1:a1, area2:a2});
				for (area in [a1, a2])
					if (explodedAreas.filter(a -> a.area1 == area || a.area2 == area).length >= AchConst.Complete_Z1_KoboldsMines_HM_Special.Explosions)
						setChallenge(owner, Ach.Complete_Z1_KoboldsMines_HM_Special, true);
