function findRockPos() {
	var tries = 50;
	var pos = skill.ownerFoe.getOrigin();
	var crab = toCrabgantua(skill.ownerFoe);
	while (tries > 0) {
		var pos = randomPosAround(skill.ownerFoe.getOrigin(), vars.range);
		if (crab.checkShardDistance(pos, vars.minRange) && crab.checkGeyserDistance(pos, 9)) {
